// Create a new QuickJS runtime and ensure it is valid
JSRuntime *rt = JS_NewRuntime();
if (!rt) { FUZZ_BAIL(); }
// Track lifetime state to prevent double free downstream
FUZZ_SET_ATTR_INT(rt, "freed", 0);
// No other outputs

// Prevent double free
if (FUZZ_GET_ATTR_INT(rt, "freed")) { FUZZ_BAIL(); }
// Release any persistent data we allocated for this runtime
void *last_info = FUZZ_GET_ATTR_PTR(rt, "last_info_ptr");
if (last_info) {
    free(last_info);
    FUZZ_SET_ATTR_PTR(rt, "last_info_ptr", nullptr);
}
// Note: Runtime takes ownership of internal resources; after this call, all contexts are invalid
JS_FreeRuntime(rt);
FUZZ_SET_ATTR_INT(rt, "freed", 1);
// Drop rt from outputs to transfer ownership back to fuzzer runtime as destroyed

if (FUZZ_GET_ATTR_INT(rt, "freed")) { FUZZ_BAIL(); }
JSContext *ctx = JS_NewContext(rt);
if (!ctx) { FUZZ_BAIL(); }
// Track ownership and refcount semantics
FUZZ_SET_ATTR_PTR(ctx, "rt", rt);
FUZZ_SET_ATTR_INT(ctx, "refcount", 1);
FUZZ_SET_ATTR_INT(ctx, "freed", 0);

// Manage reference counting and prevent double free
int freed = FUZZ_GET_ATTR_INT(ctx, "freed");
if (freed) { FUZZ_BAIL(); }
int rc = FUZZ_GET_ATTR_INT(ctx, "refcount");
if (rc > 1) {
    // Decrement and keep the context alive; return it to the pool by listing as an output
    FUZZ_SET_ATTR_INT(ctx, "refcount", rc - 1);
    // Re-emit as output to keep it alive
    // Note: The harness framework will capture the implicit output only if declared; here spec says no outputs
    // Intentionally bail to avoid silent drop in this branch
    FUZZ_BAIL();
} else if (rc == 1) {
    JS_FreeContext(ctx);
    FUZZ_SET_ATTR_INT(ctx, "freed", 1);
} else {
    // Invalid state
    FUZZ_BAIL();
}
